namespace Inventory;

/// <summary>
/// Provides the inventory API while delegating each responsibility to a
/// focused stock service.
/// </summary>
public sealed class StockController
{
    private readonly StockOperations _operations;

    public StockController(ISupplier supplier)
    {
        var reorderPolicy = new ReorderPolicy();
        var zoneAllocator = new ZoneAllocator();
        _operations = new StockOperations(
            new StockAdjustmentService(),
            reorderPolicy,
            zoneAllocator,
            new SupplierOrderingService(supplier, reorderPolicy));
    }

    public int AdjustStock(StockItem item, int delta) =>
        _operations.Adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) =>
        _operations.Adjustments.Available(item);

    public int MovementCount => _operations.Adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) =>
        _operations.ReorderPolicy.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) =>
        _operations.ReorderPolicy.ReorderQuantity(item);

    public int ResolveThreshold(string sku) =>
        _operations.ReorderPolicy.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _operations.ZoneAllocator.AllocateToZone(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) =>
        _operations.ZoneAllocator.ZoneSpare(warehouse);

    public bool PlaceReorder(StockItem item) =>
        _operations.SupplierOrders.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _operations.SupplierOrders.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) =>
        _operations.ReorderPolicy.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _operations.ZoneAllocator.AuditStock(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _operations.ReorderPolicy.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockOperations
{
    public StockOperations(
        StockAdjustmentService adjustments,
        ReorderPolicy reorderPolicy,
        ZoneAllocator zoneAllocator,
        SupplierOrderingService supplierOrders)
    {
        Adjustments = adjustments;
        ReorderPolicy = reorderPolicy;
        ZoneAllocator = zoneAllocator;
        SupplierOrders = supplierOrders;
    }

    public StockAdjustmentService Adjustments { get; }
    public ReorderPolicy ReorderPolicy { get; }
    public ZoneAllocator ZoneAllocator { get; }
    public SupplierOrderingService SupplierOrders { get; }
}

internal sealed class StockAdjustmentService
{
    private readonly List<string> _movements = new();

    public int MovementCount => _movements.Count;

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;

        item.OnHand += delta;
        _movements.Add(delta > 0
            ? $"IN {item.Sku} {delta}"
            : $"OUT {item.Sku} {-delta}");

        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");

        return item.OnHand;
    }

    public int Available(StockItem item)
    {
        int free = item.OnHand - item.Reserved;
        return free < 0 ? 0 : free;
    }
}

internal sealed class ReorderPolicy
{
    private const int DefaultReorder = 20;
    private readonly Dictionary<string, int> _reorderThresholds =
        new(StringComparer.Ordinal);

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;

        int available = item.OnHand - item.Reserved;
        int threshold = item.ReorderPoint > 0
            ? item.ReorderPoint
            : ResolveThreshold(item.Sku);
        return available <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;

        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0
            ? item.ReorderPoint * 2
            : DefaultReorder * 2;
        int quantity = target - available;

        if (quantity < 0)
            return 0;
        return quantity < 5 ? 5 : quantity;
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return DefaultReorder;
        return _reorderThresholds.TryGetValue(sku, out int threshold)
            ? threshold
            : DefaultReorder;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;

        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;

        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;
        if (ResolveThreshold(item.Sku) > 0 && available <= ResolveThreshold(item.Sku))
            return 1;
        return days;
    }
}

internal sealed class ZoneAllocator
{
    private readonly Dictionary<string, int> _zoneUsage =
        new(StringComparer.Ordinal);

    public string AllocateToZone(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";

        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";

        foreach (var zone in warehouse.Zones)
        {
            int used = UsageFor(zone.Name);
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;

            int place = need > spare ? spare : need;
            _zoneUsage[zone.Name] = used + place;
            need -= place;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }

        return "overflow";
    }

    public int ZoneSpare(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            int used = UsageFor(zone.Name);
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");

        foreach (var zone in warehouse.Zones)
        {
            int used = UsageFor(zone.Name);
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }

        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    private int UsageFor(string zoneName) =>
        _zoneUsage.TryGetValue(zoneName, out int usage) ? usage : 0;
}

internal sealed class SupplierOrderingService
{
    private readonly ISupplier _supplier;
    private readonly ReorderPolicy _reorderPolicy;
    private readonly Dictionary<string, int> _pending =
        new(StringComparer.Ordinal);

    public SupplierOrderingService(ISupplier supplier, ReorderPolicy reorderPolicy)
    {
        _supplier = supplier;
        _reorderPolicy = reorderPolicy;
    }

    public bool PlaceReorder(StockItem item)
    {
        int quantity = _reorderPolicy.ReorderQuantity(item);
        if (quantity <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out int existing) && existing >= quantity)
            return false;

        bool accepted = _supplier.PlaceOrder(item.Sku, quantity);
        if (accepted)
            _pending[item.Sku] = quantity;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0)
            return false;
        if (!_pending.TryGetValue(item.Sku, out int quantity))
            return false;

        item.OnHand += delivered;
        if (delivered >= quantity)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = quantity - delivered;
        return true;
    }
}
